package com.tihai.utils;
import org.junit.jupiter.api.Test;import org.springframework.test.util.ReflectionTestUtils;import java.util.*;import java.nio.file.*;import java.io.*;import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;import com.tihai.common.Question;
class ReviewReferenceTest {
 @Test void explicitPlatformFillAnswerIsPreferredAndUsesExactText()throws Exception{Map<String,Object> q=ReviewParser.read("<div class='singleQuesId' data='2'><h3 class='mark_name'>【填空题】测试</h3><div class='rightAnswer'>正确答案：<span class='answerCon'>标准文本</span></div></div>").get(0);assertEquals(true,q.get("gradeable"));assertEquals("标准文本",q.get("canonicalAnswer"));}

 static class Fixture {Path file;ReviewStore store;Query query=mock(Query.class);LiveProgressTracker progress=new LiveProgressTracker();ReviewReferenceService service=new ReviewReferenceService();String id;Map<String,Object> question;
  Fixture(String source,String value)throws Exception{file=Files.createTempDirectory("review-reference-").resolve("library.json");store=new ReviewStore(file);store.course("c","测试课程");question=ReviewParser.read("<div class='singleQuesId' data='1'><div class='Zy_TItle'>【单选题】测试题</div><ul><li>A. 甲</li><li>B. 乙</li></ul></div>").get(0);store.add("c","作业","测试作业","s",Collections.singletonList(question),0);id=(String)store.questions("c",false).get(0).get("id");ReflectionTestUtils.setField(service,"store",store);ReflectionTestUtils.setField(service,"query",query);ReflectionTestUtils.setField(service,"progress",progress);when(query.queryAnswerSync(any(Question.class))).thenAnswer(call->{progress.answerSource(source);return value;});}
 }
 @Test void aiReferenceIsLabelledCachedAndStrictModeStillRejectsIt()throws Exception{Fixture f=new Fixture("DeepSeek 已返回","A");f.service.ensure("c",f.id);f.service.ensure("c",f.id);verify(f.query,times(1)).queryAnswerSync(any(Question.class));assertThrows(IOException.class,()->f.store.check("c",f.id,"A"));Map<String,Object> graded=f.store.check("c",f.id,"A",true);assertEquals(true,graded.get("correct"));assertEquals(true,graded.get("referenceGrading"));assertEquals("AI参考答案",graded.get("answerSource"));assertEquals("",graded.get("platformAnswer"));assertEquals("A",graded.get("gradingAnswer"));assertEquals(0,((Number)f.store.courses().get(0).get("gradeable")).intValue());}
 @Test void questionBankSourceIsPreserved()throws Exception{Fixture f=new Fixture("题库已返回","乙");f.service.ensure("c",f.id);Map<String,Object> r=f.store.check("c",f.id,"B",true);assertEquals(true,r.get("correct"));assertEquals("题库参考答案",r.get("answerSource"));}
 @Test void learningTongAiHasItsOwnReferenceLabel()throws Exception{Fixture f=new Fixture("学习通 AI 已返回","A");f.service.ensure("c",f.id);Map<String,Object> result=f.store.check("c",f.id,"B",true);assertEquals("学习通AI参考答案",result.get("answerSource"));assertEquals(true,result.get("referenceGrading"));assertEquals("",result.get("platformAnswer"));}
 @Test void platformAnswerAlwaysOverridesCachedAiAnswer()throws Exception{Fixture f=new Fixture("DeepSeek 已返回","A");f.service.ensure("c",f.id);Map<String,Object> q=new LinkedHashMap<>(f.question);q.put("platformAnswer","B");q.put("canonicalAnswer","B");q.put("gradeable",true);f.store.add("c","作业","测试作业","s",Collections.singletonList(q),0);f.service.ensure("c",f.id);Map<String,Object> result=f.store.check("c",f.id,"B",true);assertEquals(true,result.get("correct"));assertEquals(false,result.get("referenceGrading"));assertEquals("平台公布答案",result.get("answerSource"));verify(f.query,times(1)).queryAnswerSync(any(Question.class));}
 @Test void cachedSourcesAndReferenceWrongRecordsSurviveRestart()throws Exception{Fixture f=new Fixture("DeepSeek 已返回","A");f.service.ensure("c",f.id);f.store.check("c",f.id,"B",true);ReviewStore loaded=new ReviewStore(f.file);Map<String,Object> q=loaded.questions("c",true).get(0);assertEquals("AI参考答案",q.get("referenceSource"));assertEquals("AI参考答案",((Map)q.get("wrongRecord")).get("gradingSource"));assertEquals(true,((Map)q.get("wrongRecord")).get("referenceGrading"));assertEquals(true,loaded.check("c",f.id,"A",true).get("correct"));}
 @Test void changedQuestionInvalidatesOldReference()throws Exception{Fixture f=new Fixture("DeepSeek 已返回","A");f.service.ensure("c",f.id);f.question.put("title","新的题干");f.store.add("c","作业","测试作业","s",Collections.singletonList(f.question),0);assertEquals(false,f.store.question("c",f.id).get("referenceAvailable"));f.service.ensure("c",f.id);verify(f.query,times(2)).queryAnswerSync(any(Question.class));}
 @Test void invalidAnswerDoesNotBecomeReferenceOrWrongRecord()throws Exception{Fixture f=new Fixture("题库已返回","Z");assertThrows(IOException.class,()->f.service.ensure("c",f.id));assertEquals(false,f.store.question("c",f.id).get("referenceAvailable"));assertEquals(0,f.store.questions("c",true).size());}
 @Test void wordReferenceDoesNotMasqueradeAsPlatformAnswer()throws Exception{Fixture f=new Fixture("DeepSeek 已返回","A");f.service.ensure("c",f.id);String xml=ReviewFeatureTest.xml(ReviewDocx.create(f.store.snapshot("c"),false));assertTrue(xml.contains("AI参考答案：A"));assertTrue(xml.contains("非平台标准答案"));assertFalse(xml.contains("平台公布答案：A"));}
}
